package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.widget.*;
public class BudgetActivity extends Activity{private EditText tech,sub,training,labor,admin,contingency,other;private Spinner type;private TextView result;private SharedPreferences p;@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);p=getSharedPreferences("budget",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Calculateur budgétaire",27,true));r.addView(Ui.text(this,"Aide au montage budgétaire. Le gabarit et la décision du Ministère demeurent la référence officielle.",13,false));type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"OBNL / coopérative","Entreprise privée à but lucratif"}));type.setSelection(p.getInt("type",0));r.addView(type);tech=f(r,"Technologie / outils","tech");sub=f(r,"Sous-traitance / consultation","sub");training=f(r,"Formation","training");labor=f(r,"Main-d’œuvre","labor");admin=f(r,"Administration","admin");contingency=f(r,"Contingence","contingency");other=f(r,"Autres dépenses admissibles","other");Button calc=Ui.primary(this,"Calculer et enregistrer");result=Ui.text(this,"",15,true);calc.setOnClickListener(v->calculate());r.addView(calc);r.addView(result);setContentView(Ui.wrap(this,r));calculate();}private EditText f(LinearLayout r,String h,String k){EditText e=Ui.field(this,h,p.getString(k,"0"));e.setInputType(2|8192);r.addView(e);return e;}private double n(EditText e){try{return Double.parseDouble(e.getText().toString().replace(',','.'));}catch(Exception x){return 0;}}private void calculate(){double t=n(tech)+n(sub)+n(training)+n(labor)+n(admin)+n(contingency)+n(other);double rate=type.getSelectedItemPosition()==0?.90:.65;double aid=Math.min(50000,t*rate);p.edit().putInt("type",type.getSelectedItemPosition()).putString("tech",tech.getText().toString()).putString("sub",sub.getText().toString()).putString("training",training.getText().toString()).putString("labor",labor.getText().toString()).putString("admin",admin.getText().toString()).putString("contingency",contingency.getText().toString()).putString("other",other.getText().toString()).putFloat("total",(float)t).putFloat("aid",(float)aid).apply();StringBuilder s=new StringBuilder();s.append(String.format(java.util.Locale.CANADA_FRENCH,"Budget : %.2f $\nAide théorique maximale : %.2f $\n",t,aid));if(t>0&&n(training)>t*.20)s.append("⚠ Formation dépasse 20 % du budget.\n");if(t>0&&n(admin)>t*.05)s.append("⚠ Administration dépasse 5 %.\n");if(t>0&&n(contingency)>t*.10)s.append("⚠ Contingence dépasse 10 %.\n");s.append(type.getSelectedItemPosition()==0?"Taux maximal utilisé : 90 %. Contribution du demandeur requise selon les règles du programme.":"Taux maximal utilisé : 65 %. Le cumul des aides publiques et la contribution du demandeur doivent respecter les règles du programme.");result.setText(s.toString());}}
